prompt --application/shared_components/user_interface/templates/list/quest_list
begin
wwv_flow_imp_shared.create_list_template(
 p_id=>wwv_flow_imp.id(890630545762896193)
,p_list_template_before_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="amc-TQuestList #COMPONENT_CSS_CLASSES#" id="#LIST_ID#" data-mark="Mark as done" data-unmark="Mark as not done" data-by-visit="Done, you opened it" data-by-hand="Done" data-next="Next" data-progress="{done} of {total} tasks done" data-points="{points} of {max} points" data-completed="Completed:" data-all-done="All done! You earned {points} points." data-reset-done="Progress reset. All tasks are open again.">',
'<div class="amc-TQuestList-head" hidden>',
'<div class="amc-TQuestList-ring" role="img"><svg class="amc-TQuestList-ringSvg" viewBox="0 0 36 36" aria-hidden="true" focusable="false"><circle class="amc-TQuestList-ringTrack" cx="18" cy="18" r="15.9155"></circle><circle class="amc-TQuestList-ringFill" cx="18" cy="18" r="15.9155" pathLength="100"></circle></svg><span class="amc-TQuestList-ringText" aria-hidden="true"></span><span class="amc-TQuestList-trophy fa fa-trophy" aria-hidden="true"></span></div>',
'<div class="amc-TQuestList-summary">',
'<h3 class="amc-TQuestList-title"><span class="amc-TQuestList-titleOpen">Get started</span><span class="amc-TQuestList-titleDone">You are all set</span></h3>',
'<p class="amc-TQuestList-progress"></p>',
'<p class="amc-TQuestList-points"></p>',
'</div>',
'<div class="amc-TQuestList-actions"><button type="button" class="amc-TQuestList-fold" aria-expanded="true" hidden><span class="amc-TQuestList-foldShow">Show tasks</span><span class="amc-TQuestList-foldHide">Hide tasks</span></button><button type="button" class="amc-TQuestList-reset" hidden><span class="amc-TQuestList-resetIcon fa fa-undo" aria-hidden="true"></span><span>Reset progress</span></button></div>',
'<div class="amc-TQuestList-burst" aria-hidden="true"></div>',
'</div>',
'<ol class="amc-TQuestList-list">'))
,p_list_template_after_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'</ol>',
'<p class="amc-TQuestList-status" role="status" aria-live="polite"></p>',
'</div>'))
,p_list_template_current=>'<li class="amc-TQuestList-item is-current" data-match="#A03#"><button type="button" class="amc-TQuestList-tick" aria-pressed="false" hidden><span class="amc-TQuestList-tickMark" aria-hidden="true"></span></button><a class="amc-TQuestList-link" href="#LINK#" aria-current="page"><span class="amc-TQuestList-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TQuestList-body"><span class="amc-TQuestList-label">#TEXT#</span><span class="amc-TQuestList-desc">#A01#</span><span class="amc-TQuestList-state"></span></span><span class="amc-TQuestList-pts"><span class="amc-TQuestList-ptsValue">#A02#</span> <span class="amc-TQuestList-ptsUnit">pts</span></span></a></li>'
,p_list_template_noncurrent=>'<li class="amc-TQuestList-item" data-match="#A03#"><button type="button" class="amc-TQuestList-tick" aria-pressed="false" hidden><span class="amc-TQuestList-tickMark" aria-hidden="true"></span></button><a class="amc-TQuestList-link" href="#LINK#"><span class="amc-TQuestList-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TQuestList-body"><span class="amc-TQuestList-label">#TEXT#</span><span class="amc-TQuestList-desc">#A01#</span><span class="amc-TQuestList-state"></span></span><span class="amc-TQuestList-pts"><span class="amc-TQuestList-ptsValue">#A02#</span> <span class="amc-TQuestList-ptsUnit">pts</span></span></a></li>'
,p_list_template_name=>'AMC Quest List'
,p_internal_name=>'AMC_TPL_QUEST_LIST'
,p_javascript_file_urls=>'#APP_FILES#amc-templates/amc-tpl-quest-list.js'
,p_theme_id=>42
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-quest-list.css'
,p_a01_label=>'Description'
,p_a02_label=>'Points'
,p_a03_label=>'Completion page'
,p_list_template_comment=>'Onboarding list template. Each list entry is a task: its link is the page to open, Attribute 1 a description, Attribute 2 the points it is worth (a number), Attribute 3 an optional completion page: part of a page URL or alias, such as order-confirmation, that also completes the task when visited, for tasks whose link opens a dialog. A task completes itself when the user has opened its page: the same page with at least the link''s item values, ignoring session, checksum and clear-cache values. The template''s JavaScript records visited pages in localStorage under amc-tpl-quest-list:<application id>:visits (page keys and first-visit time, at most 300) on every page that loads it, adds the page the user came back from (the referrer, same application) and records a task link as the user follows it, so the list works when it is only on the home page. The user can also tick a task or untick one, stored with the tasks already announced and whether the celebration was shown under amc-tpl-quest-list:<application id>:<list id>. Nothing leaves the browser. The head shows a progress ring, X of Y tasks done and points earned; the first open task is marked Next; tasks completed since the last view are announced politely with their points; when all are done the ring turns into a trophy with a short burst of sparks, shown once. Reset progress forgets the ticks and the visits of this list''s tasks. Template options: Manual only ignores visits, Hide points, Fold when complete folds the tasks behind Show tasks, Compact, Hero header fills the head with the primary color. Without JavaScript, or with storage blocked, it is a plain list of links. Reduced motion removes the sparks, the pop and the ring animation. English UI strings to translate in the template: Get started, You are all set, Show tasks, Hide tasks, Reset progress, pts, and the data-mark, data-by-visit, data-by-hand, data-next, data-progress, data-points, data-completed, data-all-done and data-reset-done attributes on the wrapper; {done}, {total}, {points} and {max} are filled in.'
);
end;
/
